CREATE TABLE public.master_plan_journey_settings(settings_key text PRIMARY KEY CHECK(settings_key='default'),self_assessment_interval_days smallint NOT NULL DEFAULT 15 CHECK(self_assessment_interval_days BETWEEN 1 AND 90),initial_self_assessment_target smallint NOT NULL DEFAULT 3 CHECK(initial_self_assessment_target BETWEEN 1 AND 12),updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid REFERENCES public.collaborators(id) ON DELETE SET NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.master_plan_journey_settings TO authenticated; GRANT ALL ON public.master_plan_journey_settings TO service_role; ALTER TABLE public.master_plan_journey_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY master_plan_journey_settings_read ON public.master_plan_journey_settings FOR SELECT TO authenticated USING(true); CREATE POLICY master_plan_journey_settings_admin_manage ON public.master_plan_journey_settings FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.master_plan_capability_development_plans(collaborator_id uuid NOT NULL REFERENCES public.collaborators(id) ON DELETE CASCADE,capability_code text NOT NULL REFERENCES public.master_plan_capability_library(code) ON DELETE CASCADE,target_level smallint NOT NULL CHECK(target_level BETWEEN 0 AND 3),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL REFERENCES public.collaborators(id),PRIMARY KEY(collaborator_id,capability_code));
GRANT SELECT ON public.master_plan_capability_development_plans TO authenticated; GRANT ALL ON public.master_plan_capability_development_plans TO service_role; ALTER TABLE public.master_plan_capability_development_plans ENABLE ROW LEVEL SECURITY; CREATE POLICY master_plan_development_plans_read ON public.master_plan_capability_development_plans FOR SELECT TO authenticated USING(public.is_admin() OR collaborator_id=public.current_collaborator_id()); CREATE INDEX master_plan_development_plans_capability ON public.master_plan_capability_development_plans(capability_code,target_level);
CREATE TABLE public.master_plan_responsibility_claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),collaborator_id uuid NOT NULL REFERENCES public.collaborators(id) ON DELETE CASCADE,responsibility_source_id text NOT NULL REFERENCES public.master_plan_responsibility_library(source_id) ON DELETE RESTRICT,status text NOT NULL DEFAULT 'requested' CHECK(status IN('requested','approved','rejected','cancelled')),requested_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz,decided_by uuid REFERENCES public.collaborators(id) ON DELETE SET NULL,decision_note text NOT NULL DEFAULT '' CHECK(length(decision_note)<=4000));
GRANT SELECT ON public.master_plan_responsibility_claims TO authenticated; GRANT ALL ON public.master_plan_responsibility_claims TO service_role; ALTER TABLE public.master_plan_responsibility_claims ENABLE ROW LEVEL SECURITY; CREATE POLICY master_plan_responsibility_claims_read ON public.master_plan_responsibility_claims FOR SELECT TO authenticated USING(public.is_admin() OR collaborator_id=public.current_collaborator_id()); CREATE UNIQUE INDEX master_plan_responsibility_claims_one_open ON public.master_plan_responsibility_claims(collaborator_id,responsibility_source_id) WHERE status='requested'; CREATE INDEX master_plan_responsibility_claims_queue ON public.master_plan_responsibility_claims(status,requested_at DESC);
CREATE FUNCTION public.master_plan_guard_self_assessment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE assessment_interval_days smallint; latest_assessment_at timestamptz; BEGIN PERFORM public.master_plan_assert_current_collaborator(NEW.collaborator_id); PERFORM pg_advisory_xact_lock(hashtextextended(NEW.collaborator_id::text || ':' || NEW.capability_code,0)); SELECT self_assessment_interval_days INTO assessment_interval_days FROM public.master_plan_journey_settings WHERE settings_key='default'; SELECT max(created_at) INTO latest_assessment_at FROM public.master_plan_self_assessments WHERE collaborator_id=NEW.collaborator_id AND capability_code=NEW.capability_code; NEW.created_at:=now(); IF latest_assessment_at IS NOT NULL AND NEW.created_at<latest_assessment_at+make_interval(days=>coalesce(assessment_interval_days,15)) THEN RAISE EXCEPTION 'self_assessment_interval_not_reached'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER master_plan_self_assessment_cadence_guard BEFORE INSERT ON public.master_plan_self_assessments FOR EACH ROW EXECUTE FUNCTION public.master_plan_guard_self_assessment();
CREATE FUNCTION public.master_plan_guard_certification_request() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT public.is_admin() THEN PERFORM public.master_plan_assert_current_collaborator(NEW.collaborator_id); END IF; IF TG_OP='UPDATE' AND NEW.collaborator_id IS DISTINCT FROM OLD.collaborator_id THEN RAISE EXCEPTION 'certification_request_owner_immutable'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER master_plan_certification_request_owner_guard BEFORE INSERT OR UPDATE ON public.master_plan_certification_requests FOR EACH ROW EXECUTE FUNCTION public.master_plan_guard_certification_request();
CREATE FUNCTION public.master_plan_set_capability_development_plan(p_collaborator_id uuid,p_capability_code text,p_target_level smallint) RETURNS public.master_plan_capability_development_plans LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE result public.master_plan_capability_development_plans; actor_id uuid:=public.current_collaborator_id(); BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'admin_profile_required'; END IF; IF actor_id IS NULL THEN RAISE EXCEPTION 'current_collaborator_required'; END IF; IF p_target_level NOT BETWEEN 0 AND 3 THEN RAISE EXCEPTION 'invalid_target_level'; END IF; INSERT INTO public.master_plan_capability_development_plans(collaborator_id,capability_code,target_level,updated_by) VALUES(p_collaborator_id,p_capability_code,p_target_level,actor_id) ON CONFLICT(collaborator_id,capability_code) DO UPDATE SET target_level=excluded.target_level,updated_by=excluded.updated_by,updated_at=now() RETURNING * INTO result; RETURN result; END; $$;
CREATE FUNCTION public.master_plan_request_responsibility(p_responsibility_source_id text) RETURNS public.master_plan_responsibility_claims LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE actor_id uuid:=public.current_collaborator_id(); responsibility_payload jsonb; unmet_requirement jsonb; result public.master_plan_responsibility_claims; BEGIN PERFORM public.master_plan_assert_current_collaborator(actor_id); SELECT payload INTO responsibility_payload FROM public.master_plan_responsibility_library WHERE source_id=p_responsibility_source_id; IF responsibility_payload IS NULL THEN RAISE EXCEPTION 'unknown_responsibility'; END IF; SELECT requirement.value INTO unmet_requirement FROM jsonb_array_elements(coalesce(responsibility_payload->'requiredCapabilities','[]'::jsonb)) requirement(value) WHERE coalesce((SELECT max(request.target_level) FROM public.master_plan_certification_requests request WHERE request.collaborator_id=actor_id AND request.capability_code=requirement.value->>'capabilityCode' AND request.status='approved'),0)<(requirement.value->>'minimumLevel')::smallint LIMIT 1; IF unmet_requirement IS NOT NULL THEN RAISE EXCEPTION 'responsibility_prerequisite_not_certified: %',unmet_requirement->>'capabilityCode'; END IF; INSERT INTO public.master_plan_responsibility_claims(collaborator_id,responsibility_source_id) VALUES(actor_id,p_responsibility_source_id) RETURNING * INTO result; RETURN result; END; $$;
CREATE FUNCTION public.master_plan_review_responsibility_claim(p_claim_id uuid,p_decision text,p_note text DEFAULT '') RETURNS public.master_plan_responsibility_claims LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE actor_id uuid:=public.current_collaborator_id(); result public.master_plan_responsibility_claims; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'admin_profile_required'; END IF; IF p_decision NOT IN('approved','rejected') THEN RAISE EXCEPTION 'invalid_claim_decision'; END IF; IF actor_id IS NULL THEN RAISE EXCEPTION 'current_collaborator_required'; END IF; UPDATE public.master_plan_responsibility_claims SET status=p_decision,decided_at=now(),decided_by=actor_id,decision_note=trim(coalesce(p_note,'')) WHERE id=p_claim_id AND status='requested' RETURNING * INTO result; IF result.id IS NULL THEN RAISE EXCEPTION 'claim_not_reviewable'; END IF; RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.master_plan_guard_self_assessment(),public.master_plan_guard_certification_request(),public.master_plan_set_capability_development_plan(uuid,text,smallint),public.master_plan_request_responsibility(text),public.master_plan_review_responsibility_claim(uuid,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.master_plan_set_capability_development_plan(uuid,text,smallint),public.master_plan_request_responsibility(text),public.master_plan_review_responsibility_claim(uuid,text,text) TO authenticated;